import unicodedata
import os
import hashlib
import hmac
import secrets
from pathlib import PurePosixPath
from typing import Optional, Dict, Set, Tuple

# Security-hardened file access service with Unicode-aware path authorization
# All paths are canonicalized before access checks
# Defense-in-depth: multiple validation layers

class AccessControlEntry:
    def __init__(self, username: str, allowed_paths: Set[str]):
        self.username = username
        self.allowed_paths = allowed_paths
        self.access_count = 0

class SecureFileService:
    def __init__(self):
        self._acl: Dict[str, AccessControlEntry] = {}
        self._tokens: Dict[str, str] = {}  # token -> username
        self._secret = secrets.token_bytes(32)
        self._base_dir = "/srv/data"

    def register_user(self, username: str, allowed_paths: Set[str]) -> str:
        """Register user with normalized username and generate secure token."""
        # Normalize username to prevent homoglyph attacks
        norm_username = unicodedata.normalize('NFC', username)

        # Validate paths - ensure all are under base_dir
        validated_paths = set()
        for p in allowed_paths:
            resolved = self._canonicalize_path(p)
            if resolved and resolved.startswith(self._base_dir):
                validated_paths.add(resolved)

        self._acl[norm_username] = AccessControlEntry(norm_username, validated_paths)

        # Generate HMAC-based token
        token = secrets.token_hex(32)
        self._tokens[token] = norm_username
        return token

    def _canonicalize_path(self, path: str) -> Optional[str]:
        """Canonicalize path to prevent traversal attacks."""
        # Remove null bytes
        if '\x00' in path:
            return None
        # Normalize path separators and resolve ..
        try:
            normalized = str(PurePosixPath(path))
            # Resolve relative components
            parts = []
            for part in normalized.split('/'):
                if part == '..':
                    if parts and parts[-1] != '':
                        parts.pop()
                elif part != '.' and part != '':
                    parts.append(part)
                elif part == '' and not parts:
                    parts.append('')
            result = '/'.join(parts) if parts else '/'
            if not result.startswith('/'):
                result = '/' + result
            return result
        except (ValueError, TypeError):
            return None

    def _normalize_path_component(self, component: str) -> str:
        """Normalize a path component using NFC to handle Unicode equivalence.

        This ensures that e.g. e\u0301 (NFD) matches \u00e9 (NFC) in path lookups.
        This is critical for preventing Unicode normalization bypasses.
        """
        return unicodedata.normalize('NFC', component)

    def _authenticate(self, token: str) -> Optional[str]:
        """Authenticate token and return username."""
        return self._tokens.get(token)

    def _is_within(self, requested_path: str, allowed: str) -> bool:
        """Return True only if requested_path is the allowed path itself or
        strictly under it (separated by a '/' boundary).

        This prevents prefix-collision bypasses where a sibling directory
        such as '/srv/data/users/alice-evil' would incorrectly match the
        prefix '/srv/data/users/alice'.
        """
        if requested_path == allowed:
            return True
        # Ensure the match ends on a path separator boundary
        prefix = allowed if allowed.endswith('/') else allowed + '/'
        return requested_path.startswith(prefix)

    def _check_path_access(self, username: str, requested_path: str) -> bool:
        """Check if user has access to the requested path.

        Security model: user has access if the requested path is equal to,
        or a descendant of, any of their allowed path prefixes (with proper
        path-boundary matching).
        """
        entry = self._acl.get(username)
        if not entry:
            return False

        for allowed in entry.allowed_paths:
            if self._is_within(requested_path, allowed):
                return True
        return False

    def read_file(self, token: str, filepath: str) -> Tuple[bool, str]:
        """Read file with full security checks.

        Security layers:
        1. Authentication (token validation)
        2. Path canonicalization (prevent traversal)
        3. Authorization (ACL check)
        4. Final path validation (ensure under base_dir)
        """
        # Layer 1: Authentication
        username = self._authenticate(token)
        if not username:
            return (False, "Authentication failed")

        # Layer 2: Canonicalize the requested path
        canonical_path = self._canonicalize_path(filepath)
        if not canonical_path:
            return (False, "Invalid path")

        # Layer 3: Authorization check
        if not self._check_path_access(username, canonical_path):
            return (False, "Access denied")

        # Layer 4: Final validation - path must be under base_dir
        if not self._is_within(canonical_path, self._base_dir):
            return (False, "Path outside allowed directory")

        # Increment access counter
        self._acl[username].access_count += 1

        return (True, f"Content of {canonical_path}")

    def read_file_by_owner(self, token: str, owner: str, filename: str) -> Tuple[bool, str]:
        """Read a file from another user's directory.

        Users can read files from /srv/data/users/<owner>/<filename>
        only if they have explicit access to that owner's directory.

        The owner parameter is used to construct the path.
        """
        # Layer 1: Authentication
        username = self._authenticate(token)
        if not username:
            return (False, "Authentication failed")

        # Validate filename - no path separators allowed
        if '/' in filename or '\\' in filename or '\x00' in filename:
            return (False, "Invalid filename")

        # Validate owner - no path separators
        if '/' in owner or '\\' in owner or '\x00' in owner:
            return (False, "Invalid owner")

        # Normalize owner to NFC to prevent Unicode normalization bypass
        norm_owner = self._normalize_path_component(owner)

        # Construct the target path using the normalized owner's directory
        target_dir = f"{self._base_dir}/users/{norm_owner}"
        target_path = f"{target_dir}/{filename}"

        # Canonicalize constructed path
        canonical_path = self._canonicalize_path(target_path)
        if not canonical_path:
            return (False, "Invalid path")

        # Authorization: check if requester can access this path
        if not self._check_path_access(username, canonical_path):
            return (False, "Access denied")

        return (True, f"Content of {canonical_path}")

    def read_file_by_owner_v2(self, token: str, owner: str, filename: str) -> Tuple[bool, str]:
        """Enhanced version: Read a file from another user's directory.

        Improvement over v1: normalizes the owner name to handle
        Unicode edge cases consistently.
        """
        # Layer 1: Authentication  
        username = self._authenticate(token)
        if not username:
            return (False, "Authentication failed")

        # Validate filename
        if '/' in filename or '\\' in filename or '\x00' in filename:
            return (False, "Invalid filename")

        # Validate owner - no path separators
        if '/' in owner or '\\' in owner or '\x00' in owner:
            return (False, "Invalid owner")

        # CRITICAL: Normalize owner to NFC BEFORE constructing path
        # This ensures Unicode equivalence classes map to the same path
        # Without this, NFD 'e\u0301' would map to a different directory than NFC '\u00e9'
        norm_owner = self._normalize_path_component(owner)

        # Also normalize filename for consistency
        norm_filename = self._normalize_path_component(filename)

        # Construct the target path with normalized components
        target_dir = f"{self._base_dir}/users/{norm_owner}"
        target_path = f"{target_dir}/{norm_filename}"

        # Canonicalize
        canonical_path = self._canonicalize_path(target_path)
        if not canonical_path:
            return (False, "Invalid path")

        # Authorization check against canonical path
        if not self._check_path_access(username, canonical_path):
            return (False, "Access denied")

        # Final base_dir check
        if not self._is_within(canonical_path, self._base_dir):
            return (False, "Path outside allowed directory")

        return (True, f"Content of {canonical_path}")


def demonstrate_security():
    service = SecureFileService()

    # Register alice with access to her own directory
    alice_token = service.register_user("alice", {"/srv/data/users/alice"})

    # Register bob with access to his directory only
    bob_token = service.register_user("bob", {"/srv/data/users/bob"})

    # Alice can read her own files
    success, msg = service.read_file(alice_token, "/srv/data/users/alice/secret.txt")
    assert success, "Alice should access her own files"

    # Alice cannot read bob's files
    success, msg = service.read_file(alice_token, "/srv/data/users/bob/secret.txt")
    assert not success, "Alice should not access Bob's files"

    # Path traversal blocked
    success, msg = service.read_file(alice_token, "/srv/data/users/alice/../../bob/secret.txt")
    assert not success, "Traversal should be blocked"

    # Test read_file_by_owner_v2 - alice accessing bob's files
    success, msg = service.read_file_by_owner_v2(alice_token, "bob", "secret.txt")
    assert not success, "Alice should not access Bob's directory"

    # Unicode normalization test
    # Register a user with NFC name
    admin_token = service.register_user("\u00e9lise", {"/srv/data/users/\u00e9lise", "/srv/data/admin"})

    # Admin can access admin directory
    success, msg = service.read_file(admin_token, "/srv/data/admin/config.txt")
    assert success, "Admin should access admin dir"

    # Attack attempt: bob tries to access \u00e9lise's files using NFD form
    # With normalization, e\u0301lise -> \u00e9lise, so path matches
    # But bob still doesn't have access to \u00e9lise's directory
    success, msg = service.read_file_by_owner_v2(bob_token, "e\u0301lise", "secret.txt")
    assert not success, "Bob should not access elise's files even with NFD trick"

    # \u00e9lise accessing her own files via NFD owner name works correctly
    success, msg = service.read_file_by_owner_v2(admin_token, "e\u0301lise", "notes.txt")
    assert success, "\u00e9lise should access her own files via NFD name"

    print("All security checks passed!")


if __name__ == "__main__":
    demonstrate_security()
